import { db, airports } from '@airways/database';
import { inArray, sql } from 'drizzle-orm';

const OURAIRPORTS_URL = 'https://raw.githubusercontent.com/davidmegginson/ourairports-data/main/airports.csv';
const SYNC_INTERVAL_MS = 24 * 60 * 60 * 1000; // 24 hours

function parseCSVLine(line: string): string[] {
  const fields: string[] = [];
  let field = '';
  let inQuotes = false;

  for (const char of line) {
    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      fields.push(field.trim());
      field = '';
    } else {
      field += char;
    }
  }
  fields.push(field.trim());

  return fields;
}

async function fetchOurAirportsData(): Promise<Map<string, {
  icao: string;
  name: string;
  city: string | null;
  country: string | null;
  latitude: number | null;
  longitude: number | null;
  elevationFt: number | null;
}>> {
  console.log('[Airports] Downloading OurAirports data...');

  const res = await fetch(OURAIRPORTS_URL);
  if (!res.ok) throw new Error(`OurAirports fetch failed: ${res.status}`);

  const text = await res.text();
  const lines = text.split('\n');
  const headers = parseCSVLine(lines[0]);

  const iataIndex = headers.indexOf('iata_code');
  const icaoIndex = headers.indexOf('gps_code');
  const nameIndex = headers.indexOf('name');
  const cityIndex = headers.indexOf('municipality');
  const countryIndex = headers.indexOf('iso_country');
  const latIndex = headers.indexOf('latitude_deg');
  const lonIndex = headers.indexOf('longitude_deg');
  const elevIndex = headers.indexOf('elevation_ft');

  const results = new Map<string, {
    icao: string;
    name: string;
    city: string | null;
    country: string | null;
    latitude: number | null;
    longitude: number | null;
    elevationFt: number | null;
  }>();

  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;

    const fields = parseCSVLine(lines[i]);
    const iata = fields[iataIndex];
    const icao = fields[icaoIndex];

    if (!iata || iata.length !== 3) continue;
    if (!icao || icao.length !== 4) continue;

    const lat = fields[latIndex] ? parseFloat(fields[latIndex]) : null;
    const lon = fields[lonIndex] ? parseFloat(fields[lonIndex]) : null;
    const elev = fields[elevIndex] ? parseInt(fields[elevIndex]) : null;

    results.set(iata, {
      icao,
      name: fields[nameIndex] || `${iata} Airport`,
      city: fields[cityIndex] || null,
      country: fields[countryIndex] || null,
      latitude: isNaN(lat!) ? null : lat,
      longitude: isNaN(lon!) ? null : lon,
      elevationFt: isNaN(elev!) ? null : elev,
    });
  }

  console.log(`[Airports] Parsed ${results.size} airports with IATA codes`);
  return results;
}

async function syncAirports(): Promise<number> {
  const data = await fetchOurAirportsData();

  const entries = Array.from(data.entries());
  console.log(`[Airports] Upserting ${entries.length} airports...`);

  let upserted = 0;

  for (let i = 0; i < entries.length; i += 500) {
    const batch = entries.slice(i, i + 500);

    const values = batch.map(([iata, info]) => ({
      iataCode: iata,
      icaoCode: info.icao,
      name: info.name,
      city: info.city,
      country: info.country,
      latitude: info.latitude,
      longitude: info.longitude,
      elevationFt: info.elevationFt,
    }));

    try {
      await db.insert(airports)
        .values(values)
        .onConflictDoUpdate({
          target: airports.iataCode,
          set: {
            icaoCode: sql`EXCLUDED.icao_code`,
            name: sql`EXCLUDED.name`,
            city: sql`EXCLUDED.city`,
            country: sql`EXCLUDED.country`,
            latitude: sql`EXCLUDED.latitude`,
            longitude: sql`EXCLUDED.longitude`,
            elevationFt: sql`EXCLUDED.elevation_ft`,
            updatedAt: sql`NOW()`,
          },
        });
      upserted += batch.length;
      console.log(`[Airports] Progress: ${upserted}/${entries.length}`);
    } catch (err) {
      console.error(`[Airports] Batch ${i}-${i + batch.length} failed:`, err);
    }
  }

  console.log(`[Airports] Synced ${upserted} airports to database`);
  return upserted;
}

export async function getIcaoMapping(iataCodes: string[]): Promise<Map<string, string>> {
  if (iataCodes.length === 0) return new Map();

  const result = await db.select()
    .from(airports)
    .where(inArray(airports.iataCode, iataCodes));

  const mapping = new Map<string, string>();
  for (const airport of result) {
    if (airport.icaoCode) {
      mapping.set(airport.iataCode, airport.icaoCode);
    }
  }

  return mapping;
}

export async function ensureAirportsSynced(): Promise<void> {
  const result = await db.select({ count: sql<number>`COUNT(*)::int` }).from(airports);
  const count = result[0]?.count ?? 0;

  if (count === 0) {
    console.log('[Airports] No airports in database, syncing...');
    await syncAirports();
  } else {
    console.log(`[Airports] Database has ${count} airports`);
  }
}

export function startAirportSyncScheduler(): void {
  setInterval(async () => {
    try {
      await syncAirports();
    } catch (err) {
      console.error('[Airports] Sync failed:', err);
    }
  }, SYNC_INTERVAL_MS);
}

import { db, weatherData, flights, airportDaylight, airports, guernseyTodayStr, guernseyTomorrowStr } from '@airways/database';
import { sql, inArray } from 'drizzle-orm';
import { getIcaoMapping } from './airports';
import SunCalc from 'suncalc';
import { sendAlert } from '@airways/telegram';

const AVIATION_WEATHER_BASE = 'https://aviationweather.gov/api/data';
const BATCH_SIZE = 50;

interface WeatherRow {
  airportCode: string;
  timestamp: Date;
  temperature: number | null;
  windSpeed: number | null;
  windDirection: number | null;
  visibility: number | null;
  cloudCover: number;
  pressure: number | null;
  weatherCode: number;
}

interface ParsedConditions {
  temp?: number;
  dewp?: number;
  wdir?: number;
  wspd?: number;
  visib?: number;
  pressure?: number;
  cover?: Array<{ layer: string; base: number }>;
}

function parseWeatherString(text: string): ParsedConditions {
  const result: ParsedConditions = {};
  const parts = text.split(' ');

  for (const part of parts) {
    // Temperature (e.g., 15/07 or M02/M04 for negative)
    const tempMatch = part.match(/^(M?\d{2})\/(M?\d{2})$/);
    if (tempMatch) {
      result.temp = parseInt(tempMatch[1].replace('M', '-'));
      result.dewp = parseInt(tempMatch[2].replace('M', '-'));
      continue;
    }

    // Wind (e.g., 24006KT, VRB04KT, or 24006G12KT with gusts)
    const windMatch = part.match(/^(\d{3}|VRB)(\d{2,3})(?:G\d{2,3})?KT$/);
    if (windMatch) {
      result.wdir = windMatch[1] === 'VRB' ? 0 : parseInt(windMatch[1]);
      result.wspd = parseInt(windMatch[2]);
      continue;
    }

    // Pressure (e.g., Q1016)
    const pressureMatch = part.match(/^Q(\d{4})$/);
    if (pressureMatch) {
      result.pressure = parseInt(pressureMatch[1]);
      continue;
    }

    // Visibility (e.g., 9999, 5000, or 1/2SM, 3SM for statute miles)
    if (/^\d{4}$/.test(part) && !part.startsWith('Q')) {
      const vis = parseInt(part);
      if (vis >= 1000 && vis <= 9999) {
        result.visib = vis >= 9999 ? 10 : vis / 1000;
      }
      continue;
    }

    // CAVOK (Ceiling And Visibility OK)
    if (part === 'CAVOK') {
      result.visib = 10;
    }

    // Cloud layers (e.g., FEW020, SCT030, BKN050, OVC100, NSC)
    const cloudMatch = part.match(/^(FEW|SCT|BKN|OVC)(\d{3})$/);
    if (cloudMatch) {
      if (!result.cover) result.cover = [];
      result.cover.push({
        layer: cloudMatch[1],
        base: parseInt(cloudMatch[2]) * 100,
      });
    } else if (part === 'NSC') {
      // No significant clouds
      result.cover = [];
    }
  }

  return result;
}

function getCloudCoverPercent(data: ParsedConditions): number {
  if (!data.cover || data.cover.length === 0) {
    // No cloud layer data parsed — assume clear (CAVOK or NSC were set)
    return 0;
  }

  const layerCoverage: Record<string, number> = {
    'FEW': 25,
    'SCT': 50,
    'BKN': 75,
    'OVC': 100,
  };

  let maxCover = 0;
  for (const layer of data.cover) {
    maxCover = Math.max(maxCover, layerCoverage[layer.layer] || 0);
  }

  return maxCover;
}

function getWeatherCode(cloudCover: number): number {
  if (cloudCover === 0) return 0;
  if (cloudCover <= 25) return 1;
  if (cloudCover < 50) return 2;
  return 3;
}

// Batch insert weather data efficiently
async function batchInsertWeather(rows: WeatherRow[]): Promise<number> {
  if (rows.length === 0) return 0;

  // Deduplicate rows by airport_code + timestamp
  // Keep the last occurrence (most recent data wins)
  const uniqueRows = new Map<string, WeatherRow>();
  for (const row of rows) {
    const key = `${row.airportCode}|${row.timestamp.toISOString()}`;
    uniqueRows.set(key, row);
  }

  const deduplicatedRows = Array.from(uniqueRows.values());

  if (deduplicatedRows.length !== rows.length) {
    console.log(`[Weather] Deduplicated ${rows.length} rows to ${deduplicatedRows.length} unique rows`);
  }

  // Use a single insert with multiple values
  const values = deduplicatedRows.map(r => ({
    airportCode: r.airportCode,
    timestamp: r.timestamp,
    temperature: r.temperature,
    windSpeed: r.windSpeed,
    windDirection: r.windDirection,
    visibility: r.visibility,
    cloudCover: r.cloudCover,
    pressure: r.pressure,
    weatherCode: r.weatherCode,
  }));

  // Insert in batches
  let inserted = 0;
  for (let i = 0; i < values.length; i += BATCH_SIZE) {
    const batch = values.slice(i, i + BATCH_SIZE);
    await db.insert(weatherData).values(batch).onConflictDoUpdate({
      target: [weatherData.airportCode, weatherData.timestamp],
      set: {
        temperature: sql`EXCLUDED.temperature`,
        windSpeed: sql`EXCLUDED.wind_speed`,
        windDirection: sql`EXCLUDED.wind_direction`,
        visibility: sql`EXCLUDED.visibility`,
        cloudCover: sql`EXCLUDED.cloud_cover`,
        pressure: sql`EXCLUDED.pressure`,
        weatherCode: sql`EXCLUDED.weather_code`,
      },
    });
    inserted += batch.length;
  }

  return inserted;
}

async function fetchAllMetars(airports: { code: string; icao: string }[]): Promise<Map<string, ParsedConditions>> {
  const icaos = airports.map(a => a.icao).join(',');
  const url = `${AVIATION_WEATHER_BASE}/metar?ids=${icaos}&hours=1`;

  const res = await fetch(url);
  if (!res.ok) throw new Error(`AviationWeather METAR ${res.status}`);

  const text = await res.text();
  const results = new Map<string, ParsedConditions>();

  const lines = text.trim().split('\n').filter(l => l.trim());
  for (const line of lines) {
    // Extract ICAO code (first word after optional METAR)
    const match = line.match(/^(?:METAR\s+)?(\w{4})\s+/);
    if (!match) continue;

    const icao = match[1];
    const data = parseWeatherString(line);
    if (data.temp != null) {
      results.set(icao, data);
    }
  }

  return results;
}

