    const cloudMatch = part.match(/^(FEW|SCT|BKN|OVC)(\d{3})$/);
    if (cloudMatch) {
      if (!result.cover) result.cover = [];
      result.cover.push({
        layer: cloudMatch[1],
        base: parseInt(cloudMatch[2]) * 100,
      });
    } else if (part === 'NSC') {
      // No significant clouds
      result.cover = [];
    }
  }

  return result;
}

